package com.aistock.prediction.analysis;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import java.math.*;import java.time.*;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;import org.springframework.http.HttpStatus;
/** Deterministic evidence; missing observations never become numeric zero. */
public final class AnalysisFacts {
 public static final String PROMPT="grounded-stock-analysis-v1";
 public record Facts(Map<String,String> values,JsonNode context,String hash){}
 private AnalysisFacts(){}
 public static Facts build(JsonNode e,String model,ObjectMapper m){try{
  String id=text(e,"instrumentId");if(!id.matches("(SH|SZ)[0-9]{6}"))throw invalid();UUID.fromString(text(e,"versionId"));if(!"RAW".equals(text(e,"priceBasis"))||!"AVAILABLE".equals(text(e,"state"))||!"tech-v1".equals(text(e,"formulaVersion"))||!Set.of("baostock","tushare").contains(text(e,"provider")))throw invalid();
  LocalDate from=LocalDate.parse(text(e.path("requestedRange"),"from")),to=LocalDate.parse(text(e.path("requestedRange"),"to"));if(from.isAfter(to)||from.isBefore(to.minusMonths(12)))throw invalid();var bars=e.path("bars");if(!bars.isArray()||bars.isEmpty()||bars.size()>400)throw invalid();LocalDate prior=null;JsonNode last=null,first=null;for(var b:bars){var d=LocalDate.parse(text(b,"date"));if(d.isBefore(from)||d.isAfter(to)||prior!=null&&!d.isAfter(prior))throw invalid();prior=d;var close=decimal(b,"close");if(close==null||close.signum()<=0)throw invalid();if(!b.path("tradeStatus").isIntegralNumber()||!Set.of(0,1).contains(b.path("tradeStatus").asInt()))throw invalid();if(b.path("tradeStatus").asInt()==1){if(first==null)first=b;last=b;}}if(last==null)throw invalid();
  var f=new TreeMap<String,String>();f.put("STOCK",id);f.put("RANGE_FROM",text(e.path("actualRange"),"from"));f.put("RANGE_TO",text(e.path("actualRange"),"to"));if(!f.get("RANGE_FROM").equals(bars.get(0).path("date").asText())||!f.get("RANGE_TO").equals(bars.get(bars.size()-1).path("date").asText()))throw invalid();f.put("AS_OF",text(last,"date"));BigDecimal close=decimal(last,"close");f.put("CLOSE",close.toPlainString()+"元（历史未复权收盘价）");
  for(var k:List.of("ma5","ma10","ma20")){var value=decimal(last,k);if(value!=null&&value.signum()<=0)throw invalid();String key=k.toUpperCase(Locale.ROOT);f.put(key,value==null?"指标样本不足":value.toPlainString()+"元");f.put(key+"_STATE",value==null?"指标样本不足":"收盘价"+compare(close,value)+key+"均线（仅为该日位置关系）");}
  for(var k:List.of("dif","dea","macd")){var value=decimal(last,k);f.put(k.toUpperCase(Locale.ROOT),value==null?"指标样本不足":value.toPlainString());}
  BigDecimal dif=decimal(last,"dif"),dea=decimal(last,"dea"),macd=decimal(last,"macd");f.put("MACD_STATE",dif==null||dea==null||macd==null?"指标样本不足":"DIF"+compare(dif,dea)+"DEA，MACD"+(macd.signum()>0?"为正":macd.signum()<0?"为负":"为零")+"（单日关系，不能据此确认交叉事件）");
  var rsi=decimal(last,"rsi14");if(rsi!=null&&(rsi.signum()<0||rsi.compareTo(BigDecimal.valueOf(100))>0))throw invalid();f.put("RSI14",rsi==null?"指标样本不足":rsi.toPlainString());f.put("RSI_STATE",rsi==null?"指标样本不足":"RSI14为"+rsi.toPlainString()+"，"+(rsi.compareTo(BigDecimal.valueOf(70))>=0?"处于常用较高观察区":rsi.compareTo(BigDecimal.valueOf(30))<=0?"处于常用较低观察区":"处于常用中间观察区")+"（阈值仅辅助理解，不是交易信号）");
  String freshness=text(e,"freshness");f.put("FRESHNESS_LIMIT",switch(freshness){case "FRESH"->"近期覆盖已核验，仍属于已保存日线而非实时行情";case "STALE"->"缺少预期交易日，仅解释已保存历史，不能代表最新行情";case "UNKNOWN"->"日历覆盖不足，无法确认新鲜度，仅解释已保存历史";default->throw invalid();});f.put("BASIS_LIMIT","未复权历史价格可能受除权除息影响，技术指标仅供辅助参考，不保证后续表现");
  var context=m.createObjectNode().put("instrumentId",id).put("marketVersionId",text(e,"versionId")).put("provider",text(e,"provider")).put("priceBasis","RAW").put("formulaVersion","tech-v1").put("promptVersion",PROMPT).put("providerModel",model).put("from",from.toString()).put("to",to.toString());context.set("facts",m.valueToTree(f));var hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(m.writeValueAsString(context).getBytes(StandardCharsets.UTF_8)));return new Facts(Collections.unmodifiableMap(f),context,hash);
 }catch(BusinessException x){throw x;}catch(Exception x){throw invalid();}}
 private static String compare(BigDecimal a,BigDecimal b){int c=a.compareTo(b);return c>0?"高于":c<0?"低于":"等于";}
 private static String text(JsonNode n,String k){var v=n.path(k);if(!v.isTextual()||v.asText().isBlank())throw invalid();return v.asText();}
 private static BigDecimal decimal(JsonNode n,String k){var v=n.path(k);if(v.isMissingNode()||v.isNull())return null;if(!v.isTextual()||!v.asText().matches("-?[0-9]{1,16}(\\.[0-9]{1,12})?"))throw invalid();return new BigDecimal(v.asText());}
 public static BusinessException invalid(){return new BusinessException("ANALYSIS_EVIDENCE_INVALID","行情依据不完整或不一致，暂不能生成分析",HttpStatus.UNPROCESSABLE_ENTITY);}
}